// Utvidet Atelier-skisse. Alle data og handlinger er lokale eksempler; PDF-behandling er uttrykkelig utsatt.
let moduleTabs={documents:'upload',groups:'groups',sharing:'export',internal:'rounds'},queueType='Alle',queueSource='Alle',registryYear='Alle',registrySearch='',selectedDocument='example',documentFile=null,documentPreview=false,documentEvidence=false,generationYear=2028,generated=[];
let demoGroups=[{code:'FA',name:'Finansavdelingen',active:true,builtin:true},{code:'FIN-FAG',name:'Øvrige FIN-avdelinger',active:true,builtin:true},{code:'FAG',name:'Fagdepartementene',active:true,builtin:true},{code:'POL',name:'Politisk ledelse',active:true,builtin:true},{code:'PILOT',name:'Pilotgruppen',active:false,builtin:false}];
let rules=[{id:'r1',title:'Fremleggelse av budsjettforslaget',loep:'fremleggelse',kind:'fixed',month:10,day:7,yearOffset:-1,groups:['FA']},{id:'r2',title:'Underlag til nysalderingen',loep:'nysaldering',kind:'fixed',month:11,day:10,yearOffset:0,groups:['FA']},{id:'r3',title:'Oppfølging etter fremleggelse',loep:'oppfolging',kind:'relative',anchor:'fremleggelse',offset:7,yearOffset:-1,groups:['FA']},{id:'r4',title:'Regnskapsunderlag',loep:'regnskap',kind:'fixed',month:4,day:15,yearOffset:1,groups:['FA']}];
let sharingLinks=[{id:'s1',group:'FA',name:'FA – budsjettfrister',active:true}],exportOptions={group:'FA',from:'2026-10-01',to:'2026-12-31'},insightGroup='FA',backupKind='frister';
let rounds=[{id:'round1',type:'Marskonferanse',year:2027,title:'Marskonferanse 2027'}],selectedRound='round1',responsibleFilter='Alle';
let taskRules=[{id:'tr1',title:'Samle inn underlag',month:1,day:15,responsible:'Meg (SBR)'},{id:'tr2',title:'Kvalitetssikre samlet materiale',month:2,day:1,responsible:'Person B (eksempel)'}];
let tasks=[{id:'t1',round:'round1',title:'Samle inn underlag',date:'2027-01-15',responsible:'Meg (SBR)',done:false,rule:'tr1'},{id:'t2',round:'round1',title:'Kvalitetssikre samlet materiale',date:'2027-02-01',responsible:'Person B (eksempel)',done:false,rule:'tr2'},{id:'t3',round:'round1',title:'Avklare kontaktpersoner',date:'2027-01-08',responsible:'Meg (SBR)',done:true}];
proposals.push({id:'pdemo',type:'Ny frist',sender:'Eksempeldokument R-7/2026',origin:'Dokument',title:'Supplerende eksempelinnspill til Gul bok',date:'2026-11-06',budgetYear:2027,precision:'day',category:'Gul bok',note:'Forhåndsdefinert eksempelforslag. Dette er ikke resultat av analyse av en valgt PDF.',visibility:['FA'],sourceUrl:'https://www.regjeringen.no/globalassets/departementene/fin/rundskriv/arlige/2026/r-7-2026.pdf',sourceName:'R-7/2026'});
records.find(r=>r.id==='gul-2027').time='12:00';records.find(r=>r.id==='oppfolging-2026').time='15:00';
const originalOpenEvent=openEvent;
openEvent=function(id=null,date=null){originalOpenEvent(id,date);if(!isAdmin)return;const current=id?records.find(r=>r.id===id):null;$('eventTime').value=current?.time??'';$('eventTime').disabled=current?.precision==='month';document.querySelector('#eventDialog .checkboxes').innerHTML=groupChecks(current?.visibility??[]);};
let fieldSequence=0;
function field(label,name,value='',type='text',extra=''){const id='wf-'+(++fieldSequence);return `<div class="field"><label for="${id}">${label}</label><input id="${id}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function selectField(label,name,values,value){const id='wf-'+(++fieldSequence);return `<div class="field"><label for="${id}">${label}</label><select id="${id}" name="${name}">${values.map(v=>{const [key,title]=Array.isArray(v)?v:[v,v];return `<option value="${esc(key)}" ${String(key)===String(value)?'selected':''}>${esc(title)}</option>`}).join('')}</select></div>`}
function groupChecks(selected=[],name='visibility'){return demoGroups.filter(g=>g.active||selected.includes(g.code)).map(g=>`<label><input type="checkbox" name="${name}" value="${esc(g.code)}" ${selected.includes(g.code)?'checked':''}>${esc(g.code)}${!g.active?' (inaktiv)':''}${g.code==='POL'?' – aktivt valg':''}</label>`).join('')}
function tabs(module,items){return `<div class="local-tabs" role="group" aria-label="Velg underområde">${items.map(([key,title])=>`<button type="button" data-flow="tab" data-module="${module}" data-key="${key}" aria-pressed="${moduleTabs[module]===key}">${title}</button>`).join('')}</div>`}
function screen(title,lead,content,actions=''){return header(title,lead,actions)+content}
function empty(text){return `<div class="no-data">${text}</div>`}
document.body.insertAdjacentHTML('beforeend','<dialog class="edit-dialog flow-dialog" id="workflowDialog" aria-labelledby="workflowTitle"><form id="workflowForm"><div class="dialog-header"><div><p class="eyebrow" id="workflowEyebrow"></p><h2 id="workflowTitle"></h2></div><button type="button" class="close" data-close="workflowDialog" aria-label="Lukk arbeidsflyt">×</button></div><div class="dialog-content"><div id="workflowError" class="error" role="alert" hidden></div><div id="workflowBody"></div></div><div class="dialog-footer"><button type="button" data-close="workflowDialog">Avbryt</button><button type="submit" class="primary" id="workflowSubmit"></button></div></form></dialog>');
function openWorkflow(title,eyebrow,content,submit,callback){$('workflowTitle').textContent=title;$('workflowEyebrow').textContent=eyebrow;$('workflowBody').innerHTML=content;$('workflowSubmit').textContent=submit;$('workflowError').hidden=true;$('workflowForm').onsubmit=e=>{e.preventDefault();try{const result=callback(new FormData(e.target));if(result!==false){$('workflowDialog').close();render()}}catch(error){$('workflowError').textContent=error.message;$('workflowError').hidden=false}};$('workflowDialog').showModal()}
function confirmWorkflow(title,description,button,callback){openWorkflow(title,'Bekreft handling',`<p>${description}</p>`,button,()=>callback())}
function expandedAdminView(){if(!isAdmin)return '';if(section==='queue')return expandedQueue();if(section==='register')return registryView();if(section==='phases')return phasesView();if(section==='documents')return documentsView();if(section==='groups')return groupsView();if(section==='sharing')return sharingView();if(section==='internal')return internalView();return ''}
function registryView(){const items=visible().filter(e=>(registryYear==='Alle'||String(e.budgetYear)===registryYear)&&e.title.toLocaleLowerCase('nb').includes(registrySearch.toLocaleLowerCase('nb'))).sort((a,b)=>a.date.localeCompare(b.date));return screen('Fristregister','Opprett og vedlikehold de samme fristene som vises i Kalender og Budsjettår.',`<section class="surface"><div class="field-row">${selectField('Budsjettår','registryYear',['Alle',2026,2027,2028],registryYear)}${field('Søk i tittel','registrySearch',registrySearch)}<button type="button" data-flow="registryFilter">Vis utvalget</button></div></section><section class="canvas">${listMarkup(items)}</section><p class="screen-footer">${items.length} publiserte frister. Redigering oppdaterer samme frist i alle visninger.</p>`,adminActions())}
function expandedQueue(){const sources=[...new Set([...proposals.map(p=>p.sender),...(queueSource!=='Alle'?[queueSource]:[])])],items=proposals.filter(p=>(queueType==='Alle'||p.type===queueType)&&(queueSource==='Alle'||p.sender===queueSource));return screen('Godkjenningskø','Vurder innhold, dato og synlighet før publisering.',`<section class="surface"><div class="queue-filters">${selectField('Type','queueType',['Alle','Ny frist','Endring'],queueType)}${selectField('Kilde eller innsender','queueSource',['Alle',...sources],queueSource)}<button type="button" data-flow="queueFilter">Vis utvalget</button></div><p class="hint">${items.length} av ${proposals.length} åpne forslag. Genererte årsmalforslag behandles på egen flate.</p></section><div class="queue-list" style="margin-top:18px">${items.length?items.map(p=>{const original=p.target?records.find(r=>r.id===p.target):null;return `<article class="queue-card"><div class="queue-top"><div><p class="eyebrow">${esc(p.sender)}</p><h2>${esc(p.title)}</h2><p>Budsjettår ${p.budgetYear} · ${esc(p.category)}</p></div><span class="queue-kind">${esc(p.type)}</span></div>${p.origin==='Dokument'?'<p class="prototype-note">Forhåndsdefinert eksempelforslag med konstruert uttrekksbevis. Ingen PDF er analysert i skissen.</p>':''}<div class="queue-values"><div><small>${original?'Gjeldende dato':'Foreslått dato'}</small><strong>${esc(fullDate(original??p))}</strong></div><div><small>${original?'Ny dato':'Etter godkjenning'}</small><strong>${original?esc(fullDate(p)):'Samme frist i Kalender og Budsjettår'}</strong></div></div>${p.origin==='Dokument'?'<details><summary>Se konstruert uttrekksbevis</summary><div class="evidence-field"><small>Tolket dato</small><strong>6. november 2026</strong><p class="source-text">Konstruert tekst: «Eksempelinnspill sendes innen 6. november.»</p><span class="state-pill warn">Kontroller sammenhengen manuelt</span></div></details>':''}<p class="hint">${esc(p.note??'')}</p><div class="queue-footer">${original?`<p class="hint">Synligheten beholdes: ${original.visibility.join(', ')}</p>`:`<div class="checkboxes">${demoGroups.filter(g=>g.active).map(g=>`<label><input type="checkbox" data-proposal-group="${p.id}" value="${esc(g.code)}" ${g.code==='FA'?'checked':''}>${esc(g.code)}${g.code==='POL'?' – aktivt valg':''}</label>`).join('')}</div>`}<div class="queue-buttons"><button type="button" class="primary small-button" data-approve="${p.id}">Godkjenn og publiser</button><button type="button" class="small-button" data-flow="adjustProposal" data-id="${p.id}">Juster</button><button type="button" class="small-button" data-flow="rejectProposal" data-id="${p.id}">Avvis</button></div></div></article>`}).join(''):empty('Ingen forslag med disse filtrene. Velg Alle for å se hele køen.')}</div>`)}
function documentsView(){const sub=tabs('documents',[['upload','Dokumenter'],['rules','Årsmal'],['generate','Generer budsjettår']]);if(moduleTabs.documents==='rules')return screen('Årsmal','Gjentaksregler lager forslag for et nytt budsjettår.',sub+rulesView(),'<button type="button" class="primary" data-flow="newRule">+ Ny regel</button>');if(moduleTabs.documents==='generate')return screen('Generer budsjettår','Beregn forslag fra årsmalen, kontroller dem og godkjenn enkeltvis.',sub+generationView());return screen('Dokumenter','Registrer dokumentopplysninger og se hvordan forslag og kildebevis skal presenteres.',sub+`<div class="flow-grid"><section class="surface"><div class="steps"><strong>1. Velg dokument</strong><span>2. Kontroller opplysninger</span><span>3. Uttrekksoversikt</span></div>${selectField('Budsjettår','documentYear',[2026,2027,2028],documentBudgetYear)}<div class="file-choice"><strong>Dokument (PDF)</strong><p class="hint">Kun PDF · maks 15 MB</p><input type="file" id="documentFile" accept=".pdf,application/pdf" aria-label="Velg PDF"><p class="hint" id="chosenFile">${documentFile?esc(documentFile.name):'Ingen lokal fil valgt.'}</p><button type="button" class="small-button" data-flow="exampleDocument">Bruk eksempeldokument</button></div><div class="row-actions"><button type="button" data-flow="documentPreview">Forhåndsvis opplysninger</button><button type="button" disabled>Les inn PDF</button></div><p class="prototype-note">Dokumentbehandling er utsatt etter avtale. Filinnholdet leses ikke, og opplasting oppretter ingen forslag. Knappen blir aktiv i en senere prototype.</p>${documentPreview?`<div class="registration-row"><strong>${esc(documentFile?.name??'Eksempeldokument R-7-2026.pdf')}</strong><p class="hint">Budsjettår ${documentBudgetYear} · metadata i skissen · ikke analysert</p></div>`:''}</section><section class="surface"><h2>Eksempel på uttrekksoversikt</h2><p>Se plasseringen av tolket dato, kildeutdrag og usikkerhetsflagg med forhåndsdefinerte data.</p><button type="button" data-flow="documentEvidence">Vis uttrekksoversikt</button>${documentEvidence?'<div class="evidence-grid"><div class="evidence-field"><small>Tolket dato</small><strong>6. november 2026</strong><span class="state-pill warn">Må kontrolleres</span></div><div class="evidence-field"><small>Kildeutdrag – konstruert</small><p class="source-text">«Eksempelinnspill sendes innen 6. november.»</p></div></div><p class="prototype-note">Dette er en separat skjermillustrasjon. Verdiene er ikke hentet fra filen du valgte.</p><button type="button" class="small-button" data-flow="documentQueue">Se eksempelforslaget i køen →</button>':''}</section></div>`)}
function rulesView(){return `<section class="surface"><div class="actions-line"><p>${rules.length} gjentaksregler i malen</p><button type="button" data-flow="goGenerate">Generer forslag fra malen →</button></div><div class="table-scroll"><table class="work-table"><thead><tr><th>Frist og løp</th><th>Beregning</th><th>Synlighet</th><th>Handlinger</th></tr></thead><tbody>${rules.map(r=>`<tr><td><strong>${esc(r.title)}</strong><small>${esc(r.loep)}</small></td><td>${r.kind==='relative'?`${r.offset>=0?'+':''}${r.offset} dager fra ${esc(r.anchor)}`:`${r.day}. ${MONTHS[r.month-1].toLowerCase()} · ${r.yearOffset===0?'t':r.yearOffset<0?'t−1':'t+1'}`}</td><td>${r.groups.map(g=>'<span class="group-code">'+esc(g)+'</span>').join(' ')}</td><td><div class="row-actions"><button type="button" data-flow="editRule" data-id="${r.id}">Rediger</button><button type="button" data-flow="removeRule" data-id="${r.id}">Fjern fra malen</button></div></td></tr>`).join('')}</tbody></table></div><p class="hint">Malendringer endrer ikke allerede publiserte frister. Generering gir forslag; publisering krever godkjenning.</p></section>`}
function generationView(){return `<section class="surface"><div class="steps"><strong>1. Velg år</strong><span>2. Beregn og kontroller</span><span>3. Godkjenn enkeltvis</span></div><div class="field-row">${selectField('Målbudsjettår','generationYear',[2026,2027,2028],generationYear)}<button type="button" class="primary" data-flow="generate">${generated.some(g=>g.status==='open')?'Beregn på nytt':'Beregn forslag'}</button></div><p class="hint">Ny beregning erstatter åpne genererte forslag for målåret. Publiserte frister og vanlige brukerforslag beholdes.</p></section>${generated.length?`<section class="surface"><h2>Resultat for ${generationYear}</h2><p>${generated.filter(g=>g.status==='open').length} forslag til kontroll. Dette er en egen genereringsflate, adskilt fra den løpende godkjenningskøen.</p>${generated.map(g=>`<div class="module-card"><div><strong>${esc(g.title)}</strong><p>${g.error?esc(g.error):esc(F(g.date,{day:'numeric',month:'long',year:'numeric'}))+' · '+esc(g.loep)}</p><span class="state-pill ${g.error?'warn':''}">${g.error?'Kan ikke beregnes':g.status==='published'?'Publisert':g.status==='rejected'?'Avvist':'Venter på godkjenning'}</span></div>${g.status==='open'&&!g.error?`<div><div class="checkboxes">${demoGroups.filter(x=>x.active).map(x=>`<label><input type="checkbox" data-generated-group="${g.id}" value="${esc(x.code)}" ${x.code!=='POL'&&g.groups.includes(x.code)?'checked':''}>${esc(x.code)}</label>`).join('')}</div><div class="row-actions" style="margin-top:12px"><button type="button" class="primary" data-flow="approveGenerated" data-id="${g.id}">Godkjenn og publiser</button><button type="button" data-flow="rejectGenerated" data-id="${g.id}">Avvis</button></div></div>`:''}</div>`).join('')}</section>`:''}`}
function groupsView(){const sub=tabs('groups',[['groups','Synlighetsgrupper'],['insight','Se som gruppe']]);if(moduleTabs.groups==='insight'){const items=records.filter(r=>r.published&&r.visibility.includes(insightGroup));return screen('Innsyn som gruppe','Kontroller hvilke publiserte frister en gruppe kan se.',sub+`<section class="surface"><div class="field-row">${selectField('Synlighetsgruppe','insightGroup',demoGroups.map(g=>[g.code,g.code+' – '+g.name]),insightGroup)}<button type="button" data-flow="previewGroup">Vis gruppens innsyn</button></div></section><div class="insight-banner" style="margin-top:18px">Forhåndsvisning som ${esc(insightGroup)} · ${items.length} frister. Administrative merker og redigeringshandlinger er utelatt i denne forhåndsvisningen.</div><section class="canvas"><div class="list-lines">${items.map(e=>`<div class="frist-row"><span>${esc(fullDate(e))}</span><button type="button" class="title-button" data-flow="previewEvent" data-id="${e.id}">${esc(e.title)}</button><span class="year-pill y${e.budgetYear}">${e.budgetYear}</span></div>`).join('')||empty('Ingen publiserte frister for gruppen.')}</div></section>`)}return screen('Synlighetsgrupper','Forvalt navn og aktive valg, med stabile gruppekoder.',sub+`<section class="surface"><div class="table-scroll"><table class="work-table"><thead><tr><th>Gruppe</th><th>Kode</th><th>Status</th><th>Handling</th></tr></thead><tbody>${demoGroups.map(g=>`<tr><td><strong>${esc(g.name)}</strong><small>${g.builtin?'Innebygd gruppe':'Egendefinert gruppe'}</small></td><td>${esc(g.code)}</td><td><span class="state-pill ${g.active?'':'off'}">${g.active?'Aktiv':'Inaktiv'}</span></td><td><button type="button" class="small-button" data-flow="editGroup" data-id="${esc(g.code)}">Rediger</button></td></tr>`).join('')}</tbody></table></div><p class="hint">Deaktivering fjerner gruppen fra nye valg. Fristenes eksisterende synlighet beholdes. Koden endres ikke, og grupper slettes ikke.</p></section>`,'<button type="button" class="primary" data-flow="newGroup">+ Ny gruppe</button>')}
let documentBudgetYear=2027;
