function exportItems(){return records.filter(e=>e.published&&(exportOptions.group==='ALL'||e.visibility.includes(exportOptions.group))&&(!exportOptions.from||e.date>=exportOptions.from)&&(!exportOptions.to||e.date<=exportOptions.to))}
function sharingView(){const sub=tabs('sharing',[['export','Eksporter'],['links','Kalenderabonnement'],['data','Data og sikkerhetskopi']]);if(moduleTabs.sharing==='links')return screen('Kalenderabonnement','Forvalt delingslenker separat fra nedlastede kalenderfiler.',sub+`<section class="surface"><div class="actions-line"><p>${sharingLinks.length} demolenker</p><button type="button" class="primary" data-flow="newLink">+ Ny demolenke</button></div>${sharingLinks.map(link=>`<div class="module-card"><div><strong>${esc(link.name)}</strong><p>${esc(link.group)} · <span class="state-pill ${link.active?'':'off'}">${link.active?'Aktiv':'Avskrudd'}</span></p><input class="shared-link" readonly aria-label="Demolenke ${esc(link.name)}" value="https://eksempel.invalid/kalender/DEMO-${link.id}"><small class="hint">Demolenke uten tilgangsrettighet. Kan ikke brukes i Outlook.</small></div><div class="row-actions"><button type="button" data-flow="toggleLink" data-id="${link.id}">${link.active?'Skru av':'Skru på'}</button><button type="button" data-flow="removeLink" data-id="${link.id}">Slett demolenke</button></div></div>`).join('')||empty('Ingen demolenker. Opprett en for å se flyten.')}</section><p class="screen-footer">Endelig løsning viderefører gjeldende tilgangsmodell og tokenvern. Skissen oppretter ingen ekte abonnementer.</p>`);if(moduleTabs.sharing==='data')return screen('Data og sikkerhetskopi','Se innhold, lag en demokopi og prøv en kontrollert tilbakeføring.',sub+`<div class="flow-grid"><section class="surface"><h2>Lag demokopi</h2><p>Velg om du vil arbeide med frister eller årsmal. Fristene er de samme som i de andre visningene.</p>${selectField('Datasett','backupKind',[['frister','Publiserte frister'],['mal','Årsmal – gjentaksregler']],backupKind)}<div class="export-actions"><button type="button" data-flow="saveBackup">Lagre demokopi i skissen</button><button type="button" data-flow="downloadBackup">Last ned JSON-eksempel</button></div></section><section class="surface"><h2>Importer demokopi</h2><p>Forhåndsvis hva som erstattes før du bekrefter. Tilbakeføringen gjelder bare denne skissens eksempeldata.</p><div class="preview-box"><strong>${backupKind==='frister'?demoBackup.length+' frister':ruleBackup.length+' gjentaksregler'}</strong>Sist lagrede demokopi i denne nettleserfanen.</div><button type="button" style="margin-top:18px" data-flow="previewImport">Forhåndsvis import →</button></section></div>`);const items=exportItems();return screen('Eksporter frister','Velg publikum og periode, og kontroller innholdet før eksport.',sub+`<div class="flow-grid"><section class="surface"><div class="export-form">${selectField('Publikum','exportGroup',[...demoGroups.filter(g=>g.active).map(g=>[g.code,g.code+' – '+g.name]),['ALL','Mitt fulle innsyn (FIN-internt)']],exportOptions.group)}<div></div>${field('Fra dato','exportFrom',exportOptions.from,'date')}${field('Til dato','exportTo',exportOptions.to,'date')}</div><div class="export-actions"><button type="button" class="primary" data-flow="previewExport">Oppdater forhåndsvisning</button><button type="button" data-flow="wordPreview">Se Word-oppsett</button><button type="button" data-flow="icsPreview">Se kalenderfil</button><button type="button" data-flow="downloadExport">Last ned JSON-eksempel</button></div><p class="hint">ICS-fil er et øyeblikksbilde. Løpende kalenderabonnement administreres i egen fane.</p></section><section class="surface"><h2>Innhold i utvalget</h2><p><strong>${items.length} frister</strong> · ${esc(exportOptions.group)} · ${esc(exportOptions.from||'Ingen nedre grense')} – ${esc(exportOptions.to||'Ingen øvre grense')}</p>${items.slice(0,5).map(e=>`<div class="module-card"><div><strong>${esc(e.title)}</strong><p>${esc(fullDate(e))} · Budsjettår ${e.budgetYear}</p></div></div>`).join('')||empty('Ingen frister i dette utvalget.')}${items.length>5?'<p class="hint">Og '+(items.length-5)+' til.</p>':''}</section></div>`)}
function internalView(){const sub=tabs('internal',[['rounds','Runder og gjøremål'],['mine','Mine gjøremål'],['rules','Gjøremålsregler']]);if(moduleTabs.internal==='rules')return screen('Gjøremålsregler <span class="sbr-tag">SBR-intern</span>','Regler for interne gjøremål, adskilt fra fristene i budsjettkalenderen.',sub+`<section class="surface">${taskRules.map(r=>`<div class="module-card"><div><strong>${esc(r.title)}</strong><p>${r.day}. ${MONTHS[r.month-1].toLowerCase()} · ${esc(r.responsible)}</p></div><div class="row-actions"><button type="button" data-flow="editTaskRule" data-id="${r.id}">Rediger</button><button type="button" data-flow="removeTaskRule" data-id="${r.id}">Fjern regel</button></div></div>`).join('')||empty('Ingen gjøremålsregler.')}</section>`,'<button type="button" class="primary" data-flow="newTaskRule">+ Ny gjøremålsregel</button>');if(moduleTabs.internal==='mine'){const mine=tasks.filter(t=>t.responsible==='Meg (SBR)'&&!t.done);return screen('Mine gjøremål <span class="sbr-tag">SBR-intern</span>','Interne oppgaver som er tildelt deg.',sub+`<section class="surface">${mine.map(taskMarkup).join('')||empty('Ingen åpne gjøremål tildelt deg.')}</section>`)}let round=rounds.find(r=>r.id===selectedRound)??rounds[0];if(round)selectedRound=round.id;const items=round?tasks.filter(t=>t.round===round.id&&(responsibleFilter==='Alle'||t.responsible===responsibleFilter)):[];return screen('Internkalender <span class="sbr-tag">SBR-intern</span>','Arbeidsrunder, ansvarlige og fullføring. Dette er interne gjøremål, ikke publiserte frister.',sub+`<section class="surface"><div class="field-row">${selectField('Internrunde','selectedRound',rounds.map(r=>[r.id,r.title]),selectedRound)}${selectField('Ansvarlig','responsibleFilter',['Alle','Meg (SBR)','Person B (eksempel)'],responsibleFilter)}<button type="button" data-flow="roundFilter">Vis runden</button></div>${round?`<div class="actions-line"><p>${esc(round.title)}</p><div class="row-actions"><button type="button" data-flow="syncRound">Synkroniser regler</button><button type="button" data-flow="removeRound" data-id="${round.id}">Slett runde</button></div></div><div class="field-row">${field('Hurtiginnlegging','quickTask','')}<button type="button" data-flow="quickTask">Legg til gjøremål</button><button type="button" data-flow="newTask">Fullt skjema</button></div>${items.filter(t=>!t.done).map(taskMarkup).join('')||empty('Ingen aktive gjøremål i utvalget.')}<details class="completed"><summary>Ferdige gjøremål (${items.filter(t=>t.done).length})</summary>${items.filter(t=>t.done).map(taskMarkup).join('')}</details>`:empty('Opprett en internrunde for å begynne.')}</section>`,'<button type="button" class="primary" data-flow="newRound">+ Ny internrunde</button>')}
function taskMarkup(t){return `<div class="task ${t.done?'done':''}"><input type="checkbox" data-task-toggle="${t.id}" ${t.done?'checked':''} aria-label="${t.done?'Åpne igjen':'Fullfør'} ${esc(t.title)}"><div><div class="task-title">${esc(t.title)}</div><div class="task-meta">${t.date?F(t.date,{day:'numeric',month:'long',year:'numeric'}):'Venter på dato/anker'} · ${esc(t.responsible)}${moduleTabs.internal==='mine'?' · '+esc(rounds.find(r=>r.id===t.round)?.title??''):''}</div></div><div class="row-actions"><button type="button" data-flow="editTask" data-id="${t.id}">Rediger</button><button type="button" data-flow="removeTask" data-id="${t.id}">Slett</button></div></div>`}
function expandedWeekView(){const start=startWeek(D(calendarAnchor)),end=plus(start,6),months=[iso(start).slice(0,7),iso(end).slice(0,7)],all=visible().filter(e=>calendarYears.includes(e.budgetYear)),items=all.filter(e=>e.precision==='day'&&e.date>=iso(start)&&e.date<=iso(end)),tentative=all.filter(e=>e.precision==='month'&&months.includes(e.date.slice(0,7)));return header('Frister','Se uken og åpne frister uten å miste budsjettårene.',adminActions())+`<div class="calendar-toolbar"><div class="calendar-period"><button type="button" data-action="today">I dag</button><button type="button" class="arrow" data-move="-1" aria-label="Forrige uke">‹</button><button type="button" class="arrow" data-move="1" aria-label="Neste uke">›</button><h2>${F(start,{day:'numeric',month:'short'})} – ${F(end,{day:'numeric',month:'short'})}<small class="hint">Uke ${isoWeek(start)} · ${F(end,{year:'numeric'})}</small></h2></div><div class="segmented" role="group" aria-label="Kalendervisning">${[['month','Måned'],['week','Uke'],['list','Liste']].map(([k,v])=>`<button type="button" data-calendar-mode="${k}" aria-pressed="${calendarMode===k}">${v}</button>`).join('')}</div></div>${tentative.length?'<div class="tentatives"><strong>Måned – dato ikke fastsatt</strong>'+tentative.map(e=>`<button type="button" data-detail-event="${e.id}">${esc(e.title)} · ${e.budgetYear}</button>`).join('')+'</div>':''}<section class="canvas"><div class="month-scroll" tabindex="0" aria-label="Ukekalender, kan rulles vannrett"><div class="week-surface"><div class="week-days">${Array.from({length:7},(_,i)=>{const d=plus(start,i),date=iso(d),es=items.filter(e=>e.date===date);return `<div class="week-day"><button type="button" class="week-date ${date===TODAY?'today':''}" data-day="${date}">${F(d,{weekday:'short'})}<strong>${d.getUTCDate()}</strong></button><div class="week-content"><div class="week-label">Heldagsfrister</div>${es.filter(e=>!e.time).map(e=>`<button type="button" class="cal-event y${e.budgetYear}" data-detail-event="${e.id}">${esc(e.title)}</button>`).join('')}<div class="week-label" style="margin-top:26px">Med klokkeslett</div>${es.filter(e=>e.time).map(e=>`<button type="button" class="cal-event y${e.budgetYear}" data-detail-event="${e.id}"><span class="clock-label">Frist kl. ${e.time}</span>${esc(e.title)}</button>`).join('')}</div></div>`}).join('')}</div></div></div><div class="chart-footer"><span>${items.length} datofestede frister i uken</span><span>Klokkeslett er fristtidspunkt, ikke varighet.</span></div></section>`}
function openRule(id){const r=rules.find(r=>r.id===id)??{title:'',loep:'',kind:'fixed',month:10,day:1,yearOffset:0,anchor:rules[0]?.loep??'',offset:7,groups:['FA']};openWorkflow(id?'Rediger gjentaksregel':'Ny gjentaksregel','Årsmal',field('Tittel','title',r.title,'text','required')+field('Løp (stabil funksjon)','loep',r.loep,'text','required')+selectField('Regeltype','ruleKind',[['fixed','Fast dato'],['relative','Relativ til et annet løp']],r.kind)+`<div id="ruleFixedFields" ${r.kind!=='fixed'?'hidden':''}><div class="form-grid">${selectField('Måned','month',MONTHS.map((m,i)=>[i+1,m]),r.month??10)}${field('Dag','day',r.day??1,'number','min="1" max="31"')}</div>${selectField('Årsforskyvning','yearOffset',[[-1,'Året før budsjettåret (t−1)'],[0,'Budsjettåret (t)'],[1,'Året etter (t+1)']],r.yearOffset??0)}</div><div id="ruleRelativeFields" ${r.kind!=='relative'?'hidden':''}>${selectField('Ankerløp','anchor',rules.filter(x=>x.id!==id).map(x=>[x.loep,x.title+' ('+x.loep+')']),r.anchor??rules[0]?.loep)}${field('Dager etter anker (negativt = før)','offset',r.offset??7,'number')}</div><fieldset class="visibility"><legend>Standard synlighet for forslag</legend><div class="checkboxes">${groupChecks(r.groups,'ruleGroup')}</div></fieldset><p class="hint">Lagring endrer bare årsmalen. Ingen eksisterende frist blir flyttet eller publisert.</p>`,'Lagre regel',f=>{const title=String(f.get('title')).trim(),loep=String(f.get('loep')).trim(),kind=f.get('ruleKind');if(!title||!loep)throw new Error('Fyll inn tittel og løp.');if(rules.some(x=>x.id!==id&&x.loep===loep))throw new Error('Løpet finnes allerede i eksempelets årsmal.');const groups=f.getAll('ruleGroup');if(!groups.length)throw new Error('Velg minst én synlighetsgruppe.');const value={id:id??'rule-'+Date.now(),title,loep,kind,month:Number(f.get('month')),day:Number(f.get('day')),yearOffset:Number(f.get('yearOffset')),anchor:String(f.get('anchor')??''),offset:Number(f.get('offset')),groups};if(id)Object.assign(rules.find(x=>x.id===id),value);else rules.push(value);notify('Årsmalen er oppdatert. Publiserte frister er uendret.')})}
function runGeneration(){const year=generationYear,cache=new Map();function calculate(r,seen=new Set()){if(cache.has(r.id))return cache.get(r.id);if(seen.has(r.id))throw new Error('Ankerkjeden har en sirkel.');const next=new Set([...seen,r.id]);let date;if(r.kind==='fixed'){date=new Date(Date.UTC(year+r.yearOffset,r.month-1,r.day,12));if(date.getUTCMonth()!==r.month-1||date.getUTCDate()!==r.day)throw new Error('Datoen finnes ikke i målåret.')}else{const anchor=rules.find(a=>a.loep===r.anchor);if(!anchor)throw new Error('Mangler ankerløp. Avklar ankeret før publisering.');date=plus(calculate(anchor,next),r.offset)}cache.set(r.id,date);return date}generated=rules.map(r=>{const id='generated-'+year+'-'+r.id;try{return {id,rule:r.id,title:r.title,loep:r.loep,date:iso(calculate(r)),budgetYear:year,groups:[...r.groups],status:records.some(e=>e.id===id)?'published':'open'}}catch(error){return {id,rule:r.id,title:r.title,loep:r.loep,budgetYear:year,groups:r.groups,status:'error',error:error.message}}});notify('Årsmalen er beregnet. Ingen nye frister er publisert. Kontroller forslagene enkeltvis.');render()}
function publishGenerated(id){const g=generated.find(x=>x.id===id);if(!g||g.status!=='open'||g.error)return;const groups=[...document.querySelectorAll(`[data-generated-group="${id}"]:checked`)].map(n=>n.value);if(!groups.length){notify('Velg minst én synlighetsgruppe før godkjenning.');return}if(records.some(r=>r.id===id)){notify('Forslaget er allerede publisert.');return}records.push({id:g.id,title:g.title,date:g.date,budgetYear:g.budgetYear,precision:'day',category:'Budsjett',note:'Publisert fra eksempelets årsmal.',visibility:groups,published:true});g.status='published';notify('Forslaget er publisert og er nå samme frist i Kalender og Budsjettår.');render()}
function openGroup(code){const g=demoGroups.find(g=>g.code===code);openWorkflow(g?'Rediger gruppe':'Ny synlighetsgruppe','Grupper og innsyn',field('Kode','code',g?.code??'','text','required maxlength="64" '+(g?'readonly':''))+field('Visningsnavn','name',g?.name??'','text','required maxlength="256"')+(g?`<label class="inline-toggle"><input type="checkbox" name="active" ${g.active?'checked':''}>Aktiv i nye valg</label>`:'')+'<p class="hint">Koden beholdes. Deaktivering endrer ikke eksisterende fristers synlighet eller historiske referanser.</p>',g?'Lagre gruppe':'Opprett gruppe',f=>{const key=g?.code??String(f.get('code')).trim().toUpperCase(),name=String(f.get('name')).trim();if(!/^[A-Z][A-Z0-9-]{0,63}$/.test(key))throw new Error('Koden må starte med bokstav og bare ha bokstaver, sifre eller bindestrek.');if(!name)throw new Error('Fyll inn visningsnavn.');if(!g&&demoGroups.some(x=>x.code===key))throw new Error('Koden finnes allerede, også blant inaktive grupper.');if(g){g.name=name;g.active=f.has('active')}else demoGroups.push({code:key,name,active:true,builtin:false});notify('Gruppen er oppdatert. Eksisterende fristtilordninger er beholdt.')})}
function adjustProposal(id){const p=proposals.find(p=>p.id===id),original=p.target?records.find(r=>r.id===p.target):null;openWorkflow('Juster og godkjenn','Forslag til behandling',field('Tittel','title',p.title,'text','required')+field('Dato','date',p.date,'date','required')+selectField('Budsjettår','year',[2026,2027,2028],p.budgetYear)+selectField('Kategori','category',['Budsjett','Gul bok','Regnskap'],p.category)+(original?'<p class="preview-box">Synligheten beholdes: '+original.visibility.join(', ')+'</p>':'<fieldset class="visibility"><legend>Synlig for</legend><div class="checkboxes">'+groupChecks(['FA'],'proposalGroup')+'</div></fieldset>')+'<p class="hint">Denne handlingen godkjenner og publiserer de justerte opplysningene.</p>','Godkjenn og publiser',f=>{const groups=original?.visibility??f.getAll('proposalGroup');if(!groups.length)throw new Error('Velg synlighet.');const value={title:String(f.get('title')).trim(),date:String(f.get('date')),budgetYear:Number(f.get('year')),category:String(f.get('category')),precision:'day',note:p.note,visibility:groups,published:true};if(original)Object.assign(original,value);else records.push({...p,...value,id:'published-'+p.id});proposals=proposals.filter(x=>x.id!==id);notify('Forslaget er justert, godkjent og publisert. Begge visningene bruker den oppdaterte fristen.')})}
