function exportPreview(kind){const items=exportItems();if(kind==='word')openWorkflow('Word-oppsett – forhåndsvisning','Eksport',`<div class="document-preview"><p class="eyebrow">Budsjettfrister · ${esc(exportOptions.group)}</p><h3>Fristoversikt</h3><p class="hint">${esc(exportOptions.from)} – ${esc(exportOptions.to)}</p><table>${items.map(e=>`<tr><td>${esc(fullDate(e))}</td><td>${esc(e.title)}</td><td>${e.budgetYear}</td></tr>`).join('')}</table></div><p class="prototype-note">Dette viser valg og innhold. Endelig Word-eksport viderefører offisiell FIN-mal; skissen lager ingen Word-fil.</p>`,'Lukk forhåndsvisning',()=>{});else openWorkflow('Kalenderfil – forhåndsvisning','Eksport',`<p>${items.length} frister i utvalget. En ICS-fil er et øyeblikksbilde, mens abonnementet oppdateres av kalenderklienten.</p><div class="preview-code">${esc(items.map(e=>`${fullDate(e)} | ${e.time?'kl. '+e.time+' | ':''}${e.title} | budsjettår ${e.budgetYear}`).join('\n')||'Ingen frister.')}</div><p class="prototype-note">Dette er en innholdsforhåndsvisning, ikke en reell ICS-generator. Dagens eksport av heldag, tid og tentative frister beholdes og prøves i faktisk kalenderklient ved implementering.</p>`,'Lukk forhåndsvisning',()=>{})}
function openTask(id){const task=tasks.find(t=>t.id===id);openWorkflow(task?'Rediger gjøremål':'Nytt gjøremål','SBR-intern',field('Tittel','title',task?.title??'','text','required')+field('Dato (valgfri)','date',task?.date??'','date')+selectField('Ansvarlig','responsible',['Meg (SBR)','Person B (eksempel)'],task?.responsible??'Meg (SBR)')+'<p class="hint">Gjøremålet tilhører internrunden. Det opprettes ingen frist i den ordinære kalenderen.</p>','Lagre gjøremål',f=>{const title=String(f.get('title')).trim();if(!title)throw new Error('Fyll inn tittel.');const data={title,date:String(f.get('date'))||null,responsible:String(f.get('responsible'))};if(task)Object.assign(task,data);else tasks.push({...data,id:'task-'+Date.now(),round:selectedRound,done:false});notify('Gjøremålet er lagret i internkalenderen.')})}
function openTaskRule(id){const rule=taskRules.find(x=>x.id===id);openWorkflow(rule?'Rediger gjøremålsregel':'Ny gjøremålsregel','SBR-intern',field('Tittel','title',rule?.title??'','text','required')+selectField('Måned','month',MONTHS.map((m,i)=>[i+1,m]),rule?.month??1)+field('Dag','day',rule?.day??15,'number','min="1" max="31" required')+selectField('Standard ansvarlig','responsible',['Meg (SBR)','Person B (eksempel)'],rule?.responsible??'Meg (SBR)')+'<p class="hint">Regelen brukes ved oppretting eller eksplisitt synkronisering av internrunder. Ferdige gjøremål endres ikke.</p>','Lagre regel',f=>{const value={title:String(f.get('title')).trim(),month:Number(f.get('month')),day:Number(f.get('day')),responsible:String(f.get('responsible'))};if(!value.title)throw new Error('Fyll inn tittel.');if(rule)Object.assign(rule,value);else taskRules.push({...value,id:'taskrule-'+Date.now()});notify('Gjøremålsregelen er lagret. Eksisterende gjøremål er ikke endret.')})}
function fillRound(round){for(const rule of taskRules){if(tasks.some(t=>t.round===round.id&&t.rule===rule.id))continue;const d=new Date(Date.UTC(round.year,rule.month-1,rule.day,12)),valid=d.getUTCMonth()===rule.month-1&&d.getUTCDate()===rule.day;tasks.push({id:round.id+'-'+rule.id,round:round.id,rule:rule.id,title:rule.title,date:valid?iso(d):null,responsible:rule.responsible,done:false})}}
function toggleTask(id){const task=tasks.find(t=>t.id===id);if(!task)return;if(!task.done&&task.responsible!=='Meg (SBR)'){render();confirmWorkflow('Fullfør for en annen ansvarlig?',`«${esc(task.title)}» er tildelt ${esc(task.responsible)}. Vil du markere det som fullført?`,'Ja, meld fullført',()=>{task.done=true;notify('Gjøremålet er fullført på vegne av den ansvarlige.')})}else{task.done=!task.done;render();notify(task.done?'Gjøremålet er fullført.':'Gjøremålet er åpnet igjen.')}}
function previewEvent(id){const e=records.find(r=>r.id===id);openWorkflow(e.title,'Leservisning som '+insightGroup,`<p>${esc(fullDate(e))} · Budsjettår ${e.budgetYear}</p>${e.sourceUrl?'<section class="source-section"><h3>Kilderundskriv</h3><a href="'+esc(e.sourceUrl)+'" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">Les rundskrivet på regjeringen.no ↗</a></section>':''}<h3>Om fristen</h3><p>${esc(e.note)}</p>`,'Tilbake',()=>{})}
